d={}
def argument():
 print('argument')
 return 1
try:d.keys(argument())
except TypeError:print('keys')
try:d.values(value=argument())
except TypeError:print('values')
try:d.items(*[argument()])
except TypeError:print('items')
print(d)

class C:
 def __getattribute__(self,name):
  print('lookup',name)
  return lambda:[name]
c=C()
print(c.keys(),c.values(),c.items())

from collections import Counter,defaultdict
for d in (Counter({'a':2}),defaultdict(int,{'a':2})):
 print(list(d.keys()),list(d.values()),list(d.items()))

for name in ('keys','values','items'):
 d={'a':1,'b':2}
 view=getattr(d,name)()
 iterator=iter(view)
 next(iterator)
 d['c']=3
 try:next(iterator)
 except RuntimeError:print(name,'changed')
